package com.aistock.prediction.modelcatalog;
import com.aistock.prediction.analysis.*;import com.aistock.prediction.maas.*;import com.fasterxml.jackson.databind.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
@Tag("mysql") class AnalysisMysqlTest {
 final ObjectMapper m=new ObjectMapper();final Instant now=Instant.parse("2026-10-07T07:00:00Z");
 @Test void ownOperationReplayContextCacheConflictAndSharedLease()throws Exception{var db=new ModelDatabaseFixture();var r=new AnalysisRepository(db.jdbc,m);var u=UUID.randomUUID();var input=new AnalysisInput(UUID.randomUUID(),"SH600030",LocalDate.parse("2026-07-07"),LocalDate.parse("2026-10-07"),UUID.randomUUID());var facts=new AnalysisFacts.Facts(Map.of("AS_OF","2026-09-30"),m.createObjectNode(),"a".repeat(64));assertNull(r.replay(u,input,now));var claim=r.claim(u,input,facts,now);assertTrue(claim.execute());assertEquals("RUNNING",r.replay(u,input,now).path("state").asText());var gate=new MaasOperationGate(db.jdbc);assertThrows(com.aistock.common.BusinessException.class,()->gate.lockAndAcquire("PREDICTION_EXPLANATION",UUID.randomUUID(),now));var done=r.complete(input.operationId(),m.createArrayNode(),null,now.plusSeconds(2));assertEquals("SUCCEEDED",done.path("state").asText());var saved=UUID.fromString(done.path("analysisId").asText());assertNotNull(r.get(u,saved));assertThrows(com.aistock.common.BusinessException.class,()->r.get(UUID.randomUUID(),saved));assertThrows(com.aistock.common.BusinessException.class,()->r.replay(u,new AnalysisInput(input.operationId(),"SH600000",input.from(),input.to(),input.marketVersionId()),now));var cached=r.claim(u,new AnalysisInput(UUID.randomUUID(),input.instrumentId(),input.from(),input.to(),input.marketVersionId()),facts,now.plusSeconds(3));assertFalse(cached.execute());assertEquals(saved.toString(),cached.receipt().path("analysisId").asText());}
 @Test void expiredLeaseAndLateResultDoNotClearAnotherType()throws Exception{var db=new ModelDatabaseFixture();var r=new AnalysisRepository(db.jdbc,m);var u=UUID.randomUUID();var input=new AnalysisInput(UUID.randomUUID(),"SH600030",LocalDate.parse("2026-07-07"),LocalDate.parse("2026-10-07"),UUID.randomUUID());r.claim(u,input,new AnalysisFacts.Facts(Map.of(),m.createObjectNode(),"b".repeat(64)),now);var gate=new MaasOperationGate(db.jdbc);var newer=UUID.randomUUID();gate.lockAndAcquire("PREDICTION_EXPLANATION",newer,now.plusSeconds(51));assertEquals("FAILED",r.complete(input.operationId(),m.createArrayNode(),null,now.plusSeconds(52)).path("state").asText());assertEquals(newer.toString(),db.jdbc.queryForObject("select operation_id from prediction_explanation_slot",String.class));}

 @Test void predictionChoiceIsPartOfRequestAndRecoveryKeepsOriginal(){var db=new ModelDatabaseFixture();var r=new AnalysisRepository(db.jdbc,m);var u=UUID.randomUUID();var pred=UUID.randomUUID();var input=new AnalysisInput(UUID.randomUUID(),"SH600030",LocalDate.parse("2026-07-07"),LocalDate.parse("2026-10-07"),UUID.randomUUID(),pred);var context=m.createObjectNode();context.putObject("prediction").put("predictionId",pred.toString());r.claim(u,input,new AnalysisFacts.Facts(Map.of(),context,"d".repeat(64)),now);assertEquals(pred.toString(),r.replay(u,input,now).path("predictionId").asText());assertThrows(com.aistock.common.BusinessException.class,()->r.replay(u,new AnalysisInput(input.operationId(),input.instrumentId(),input.from(),input.to(),input.marketVersionId(),UUID.randomUUID()),now));}
}